parameters.jsCode:
// --- CONFIGURATION ---
const COLUMN_MAPPING = {
    DATE: 'วันที่',        
    COMPANY: 'ลูกค้า',    
    SERVICE: 'ภาพรวม service %',       
    SUPPORT: 'ภาพรวม support %',       
    OVERALL: 'overall %',
};

const data = $input.all().map(item => item.json);

// Helper function: แปลง String เปอร์เซ็นต์
const parsePercentage = (value) => {
    if (typeof value === 'string' && value.endsWith('%')) {
        return parseFloat(value.replace('%', ''));
    }
    return parseFloat(value);
};

// --- Part 1: Overall Averages & Find Latest Date ---
let totalService = 0;
let totalSupport = 0;
let totalOverall = 0;
let validCount = 0;
let latestDate = null;

for (const row of data) {
    if (!row[COLUMN_MAPPING.OVERALL] || !row[COLUMN_MAPPING.DATE]) continue; 

    const service = parsePercentage(row[COLUMN_MAPPING.SERVICE]);
    const support = parsePercentage(row[COLUMN_MAPPING.SUPPORT]);
    const overall = parsePercentage(row[COLUMN_MAPPING.OVERALL]);

    if (!isNaN(overall)) {
        totalService += isNaN(service) ? 0 : service;
        totalSupport += isNaN(support) ? 0 : support;
        totalOverall += overall;
        validCount++;
    }

    const currentDate = new Date(row[COLUMN_MAPPING.DATE]);
    if (currentDate instanceof Date && !isNaN(currentDate)) {
        if (!latestDate || currentDate > latestDate) {
            latestDate = currentDate;
        }
    }
}

const overallAverages = {
    Service: validCount > 0 ? (totalService / validCount).toFixed(2) : 'N/A',
    Support: validCount > 0 ? (totalSupport / validCount).toFixed(2) : 'N/A',
    Overall: validCount > 0 ? (totalOverall / validCount).toFixed(2) : 'N/A',
};

// --- Part 2: Filter for Latest Month & Calculate Per-Company Scores ---
let latestMonthData = [];
let latestMonthYearName = 'N/A';
let companyScoresMap = new Map();

let latestTotalService = 0;
let latestTotalSupport = 0;
let latestValidCount = 0;

if (latestDate) {
    const latestMonth = latestDate.getMonth();
    const latestYear = latestDate.getFullYear();
    latestMonthYearName = latestDate.toLocaleString('th-TH', { month: 'long', year: 'numeric' });

    for (const row of data) {
        const rowDate = new Date(row[COLUMN_MAPPING.DATE]);

        if (rowDate.getMonth() === latestMonth && rowDate.getFullYear() === latestYear) {
            latestMonthData.push(row);

            const service = parsePercentage(row[COLUMN_MAPPING.SERVICE]);
            const support = parsePercentage(row[COLUMN_MAPPING.SUPPORT]);
            const overall = parsePercentage(row[COLUMN_MAPPING.OVERALL]);

            if (!isNaN(overall)) {
                latestTotalService += isNaN(service) ? 0 : service;
                latestTotalSupport += isNaN(support) ? 0 : support;
                latestValidCount++;
            }

            const companyName = row[COLUMN_MAPPING.COMPANY];
            if (companyName) {
                if (!companyScoresMap.has(companyName)) {
                    companyScoresMap.set(companyName, {
                        company: companyName,
                        service: [],
                        support: [],
                        overall: []
                    });
                }

                const companyData = companyScoresMap.get(companyName);
                if (!isNaN(service)) companyData.service.push(service);
                if (!isNaN(support)) companyData.support.push(support);
                if (!isNaN(overall)) companyData.overall.push(overall);
            }
        }
    }
}

// ⭐ คำนวณคะแนนเฉลี่ยของแต่ละบริษัท
const companyScores = [];
let sumOfCompanyAverages = 0; // ⭐ ตัวแปรสำหรับรวมคะแนนเฉลี่ยของแต่ละบริษัท

for (const [companyName, scores] of companyScoresMap) {
    const avgService = scores.service.length > 0 
        ? scores.service.reduce((a, b) => a + b, 0) / scores.service.length 
        : 0;
    const avgSupport = scores.support.length > 0 
        ? scores.support.reduce((a, b) => a + b, 0) / scores.support.length 
        : 0;
    const avgOverall = scores.overall.length > 0 
        ? scores.overall.reduce((a, b) => a + b, 0) / scores.overall.length 
        : 0;

    // คำนวณคะแนนเฉลี่ยรวม: (Service + Support + Overall) / 3
    const finalAverage = (avgService + avgSupport + avgOverall) / 3;

    companyScores.push({
        company: companyName,
        averageScore: finalAverage.toFixed(2)
    });

    sumOfCompanyAverages += finalAverage; // ⭐ รวมคะแนนของแต่ละบริษัท
}

// ⭐ คำนวณค่าเฉลี่ยของเดือนล่าสุด
const companyCount = companyScores.length;
const latestMonthAverages = {
    Service: latestValidCount > 0 ? (latestTotalService / latestValidCount).toFixed(2) : 'N/A',
    Support: latestValidCount > 0 ? (latestTotalSupport / latestValidCount).toFixed(2) : 'N/A',
    Overall: companyCount > 0 ? (sumOfCompanyAverages / companyCount).toFixed(2) : 'N/A', // ⭐ คำนวณจากค่าเฉลี่ยของบริษัท
};

const companyList = companyScores.map(c => c.company);

// Final result
const summary = {
    LatestMonthAverages: latestMonthAverages,
    OverallAverages: overallAverages,
    LatestMonthName: latestMonthYearName,
    LatestMonthCompanyCount: companyList.length,
    LatestMonthCompanyList: companyList,
    CompanyScores: companyScores
};

return [{ json: summary }];

// --- CONFIGURATION ---
const CONFIG = {
    MAX_COMPANIES: 8,
    LOGO_URL: "https://img5.pic.in.th/file/secure-sv1/logo-19cd4303f4a43cd10.jpg",
    DASHBOARD_URL: "https://docs.google.com/spreadsheets/d/1GH4U3opsnzcD3f_EZPZSA2nrKSQFUGTwgux6IQNwMGY/edit?gid=1808953691#gid=1808953691",
    COLORS: {
        EXCELLENT: "#00897B",
        GOOD: "#F57C00",
        CRITICAL: "#C62828",
        EXCELLENT_BG: "#E0F2F1",
        GOOD_BG: "#FFF3E0",
        CRITICAL_BG: "#FFEBEE"
    },
    THRESHOLDS: {
        EXCELLENT: 80,
        GOOD: 60
    }
};

// --- HELPER FUNCTIONS ---
const formatScore = (score) => {
    const num = parseFloat(score);
    return num.toFixed(2) + "%";
};

const createProgressBar = (score, color) => {
    const barWidth = Math.min(100, Math.max(0, Math.round(score)));
    return {
        "type": "box",
        "layout": "vertical",
        "contents": [
            {
                "type": "box",
                "layout": "horizontal",
                "contents": [
                    {
                        "type": "box",
                        "layout": "vertical",
                        "contents": [],
                        "width": `${barWidth}%`,
                        "backgroundColor": color,
                        "height": "6px",
                        "cornerRadius": "3px"
                    }
                ],
                "backgroundColor": "#E0E0E0",
                "height": "6px",
                "cornerRadius": "3px"
            }
        ]
    };
};

const getScoreColor = (score) => {
    if (score >= CONFIG.THRESHOLDS.EXCELLENT) return CONFIG.COLORS.EXCELLENT;
    if (score >= CONFIG.THRESHOLDS.GOOD) return CONFIG.COLORS.GOOD;
    return CONFIG.COLORS.CRITICAL;
};

const getScoreBg = (score) => {
    if (score >= CONFIG.THRESHOLDS.EXCELLENT) return CONFIG.COLORS.EXCELLENT_BG;
    if (score >= CONFIG.THRESHOLDS.GOOD) return CONFIG.COLORS.GOOD_BG;
    return CONFIG.COLORS.CRITICAL_BG;
};

const getScoreLabel = (score) => {
    if (score >= CONFIG.THRESHOLDS.EXCELLENT) return "EXCELLENT";
    if (score >= CONFIG.THRESHOLDS.GOOD) return "GOOD";
    return "NEEDS ATTENTION";
};

const getTimestamp = () => {
    return new Date().toLocaleString('th-TH', { 
        timeZone: 'Asia/Bangkok',
        year: 'numeric',
        month: 'short',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
    });
};

// --- START MAIN LOGIC ---
try {
    // FIX 1: ดึง Reply Token
    const webhookData = $('Webhook1').first().json;

    if (!webhookData || !webhookData.body || !webhookData.body.events || !webhookData.body.events[0]) {
        throw new Error('Invalid webhook data structure');
    }

    const replyToken = webhookData.body.events[0].replyToken;

    if (!replyToken) {
        throw new Error('Reply token is missing');
    }

    // FIX 2: ดึงข้อมูลสรุป
    const inputData = $input.all();

    if (!inputData || inputData.length === 0) {
        throw new Error('No input data available');
    }

    const summary = inputData[0].json;

    if (!summary || !summary.LatestMonthAverages) {
        throw new Error('Missing required summary data');
    }

    const { 
        LatestMonthAverages, 
        LatestMonthName, 
