// สร้างวัตถุ Date ปัจจุบัน
const tomorrow = new Date();
tomorrow.setDate(tomorrow.getDate() + 1); 

// ⭐ แก้ไข: ไม่ใช้ padStart เพื่อให้ตรงกับ Google Sheets
const dd = String(tomorrow.getDate()); // 2 แทน 02
const mm = String(tomorrow.getMonth() + 1); // 12 แทน 12
const yyyy = tomorrow.getFullYear();

// ตัวแปรที่ใช้ในการค้นหาใน Google Sheet
const searchDate = `${dd}/${mm}/${yyyy}`; // 2/12/2025

console.log('Search Date:', searchDate); // ⭐ เพิ่ม log เพื่อ debug

return [{ json: { searchDate: searchDate, tomorrowDate: searchDate } }];

const items = $input.all();
const now = new Date(); // เวลาปัจจุบันที่ Workflow ทำงาน

// กำหนดขอบเขตเวลา
// 1. เริ่มต้นวันนี้ (Today Start)
const todayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate());

// 2. เริ่มต้นสัปดาห์นี้ (Week Start) - ให้นับวันจันทร์เป็นวันแรก
const dayOfWeek = now.getDay() || 7; // เปลี่ยน Sunday(0) ให้เป็น 7
const weekStart = new Date(todayStart);
weekStart.setDate(weekStart.getDate() - dayOfWeek + 1);

let total = 0;
let countToday = 0;
let countWeek = 0;

// Function สำหรับแปลงวันที่จาก Format "21/1/2026 14:29:12" เป็น Date Object
function parseCustomDate(dateString) {
  if (!dateString) return null;
  const parts = dateString.split(' ');
  if (parts.length < 2) return null;

  const dateParts = parts[0].split('/'); // แยก 21, 1, 2026
  const timeParts = parts[1].split(':'); // แยก 14, 29, 12

  // สร้าง Date Object (Year, Month-1, Day, Hour, Minute, Second)
  return new Date(
    dateParts[2], 
    dateParts[1] - 1, 
    dateParts[0], 
    timeParts[0], 
    timeParts[1], 
    timeParts[2]
  );
}

for (const item of items) {
  // ดึงค่าจาก Column "Timestamp" (ต้องตรงกับหัวตารางเป๊ะๆ)
  const rawDate = item.json.Timestamp; 

  if (rawDate) {
    const regDate = parseCustomDate(rawDate);

    if (regDate) {
      // 1. นับ Total (นับทุกแถวที่มีวันที่)
      total++;

      // 2. นับ Today
      if (regDate >= todayStart) {
        countToday++;
      }

      // 3. นับ This Week
      if (regDate >= weekStart) {
        countWeek++;
      }
    }
  }
}

return [
  {
    json: {
      summary_total: total,
      summary_today: countToday,
      summary_week: countWeek,
      report_date: now.toLocaleDateString('th-TH')
    }
  }
];

