parameters.jsCode:
// เรียกความจำ Global
const sd = $getWorkflowStaticData('global');

// ดึง UserId จาก Webhook (ต้นทาง)
const userId = $('Webhook').item.json.body.events[0].source.userId;

// ลบข้อมูลสถานะทิ้ง (จบงาน)
if (userId && sd[userId]) {
  delete sd[userId];
}

return [{ json: { status: "State Cleared", userId: userId, finished: true } }];

// ... (ส่วนที่ 1-3 เหมือนเดิม) ...
// ==========================================
// ส่วนที่ 1: รับข้อมูลจาก Tally
// ==========================================
const fields = $input.item.json.body.data.fields;
const result = {};

fields.forEach(field => {
  const key = field.label.trim();
  if (field.type === 'DROPDOWN' || field.type === 'MULTIPLE_CHOICE') {
    const selectedOption = field.options.find(opt => opt.id === field.value[0]);
    result[key] = selectedOption ? selectedOption.text : '-';
  } else if (field.type === 'FILE_UPLOAD') {
    result[key] = (field.value && field.value.length > 0) ? field.value[0].url : null;
  } else {
    result[key] = field.value || '-';
  }
});

const reporter = result['ชื่อผู้แจ้ง'] || 'Unknown';
const customerName = result['ชื่อลูกค้า'] || '-';
const serviceName = result['ชื่อบริการ'] || '-';
let issueType = result['ประเภทปัญหา'] || 'Incident';
const subject = result['รายละเอียด/อาการ'] || '-';
const imageUrl = result['รูปภาพประกอบ'];

// ==========================================
// ส่วนที่ 2: Logic วิเคราะห์ Priority & SLA
// ==========================================
const text = subject.toLowerCase();
const failureKeywords = ['ไม่ได้', 'not', 'error', 'fail', 'พัง', 'เสีย', 'ล่ม', 'เข้าไม่', 'bug', 'ผิดพลาด', 'ไม่ขึ้น', 'ไม่แสดง', 'cannot', 'รายงานผิด'];
const requestKeywords = ['ขอ', 'request', 'เพิ่ม', 'ปรับ', 'แก้ไข', 'install', 'ติดตั้ง', 'สร้าง', 'create', 'new user', 'access'];

if (failureKeywords.some(k => text.includes(k))) { issueType = 'Incident'; }
else if (requestKeywords.some(k => text.includes(k))) { issueType = 'Request'; }

let priority = 'P3';
let sla_minutes = 480; 

if (issueType === 'Request') {
    priority = 'P4';
    sla_minutes = 1440; 
} else {
    if (text.includes('ล่ม') || text.includes('ใช้งานไม่ได้ทั้งหมด') || text.includes('เข้าไม่ได้') || text.includes('down') || text.includes('critical') || text.includes('ออกรายงานไม่ได้') || text.includes('รายงานผิด')) {
        priority = 'P1'; sla_minutes = 43; 
    } else if (text.includes('ไม่ได้') || text.includes('error') || text.includes('fail') || text.includes('ไม่ขึ้น')) {
        priority = 'P2'; sla_minutes = 120; 
    } else if (text.includes('บางส่วน') || text.includes('ช้า')) {
        priority = 'P3'; sla_minutes = 240; 
    } else {
        priority = 'P4'; sla_minutes = 1440; 
    }
}

let slaText = "";
if (sla_minutes >= 60) {
    const hrs = Math.floor(sla_minutes / 60);
    const mins = sla_minutes % 60;
    slaText = mins === 0 ? `${hrs} ชั่วโมง` : `${hrs} ชม. ${mins} นาที`;
} else {
    slaText = `${sla_minutes} นาที`;
}

// ==========================================
// ส่วนที่ 3: จัดการเวลา
// ==========================================
const now = new Date();
function formatDateTime(dateObj) {
    const d = String(dateObj.getDate()).padStart(2, '0');
    const m = String(dateObj.getMonth() + 1).padStart(2, '0');
    const y = dateObj.getFullYear();
    const hr = String(dateObj.getHours()).padStart(2, '0');
    const min = String(dateObj.getMinutes()).padStart(2, '0');
    return `${d}/${m}/${y} ${hr}:${min}`;
}
const createdTimeStr = formatDateTime(now);
const due_at = new Date(now.getTime() + sla_minutes * 60 * 1000);
const dueTimeStr = formatDateTime(due_at);

const y_id = now.getFullYear().toString().slice(2);
const m_id = String(now.getMonth() + 1).padStart(2, '0');
const d_id = String(now.getDate()).padStart(2, '0');
const randomNum = Math.floor(Math.random() * 900 + 100); 
const ticketId = `OCM-${y_id}${m_id}${d_id}-${randomNum}`;
const status = "🆕 รับเรื่องแล้ว";
const assignee = issueType === 'Incident' ? 'Team Infra' : 'Service Desk';

// ==========================================
// ส่วนที่ 4: กำหนดสี (Color Logic ใหม่ ✨)
// ==========================================
let headerColor = "#1DB446"; 
let headerText = "New Ticket";

if (issueType === 'Request') {
    // 🔵 กรณีเป็น Request -> สีฟ้า
    headerColor = "#03A9F4"; // Light Blue
    headerText = "📋 Service Request";
} else {
    // 🔴 กรณีเป็น Incident -> ไล่เฉดสีแดง/ส้ม/เหลือง ตามความแรง
    if (priority === 'P1') {
        headerColor = "#D32F2F"; // Red (Critical)
        headerText = "🚨 Critical Incident (P1)";
    } else if (priority === 'P2') {
        headerColor = "#F57C00"; // Orange (High)
        headerText = "⚠️ High Priority Incident";
    } else {
        headerColor = "#FBC02D"; // Yellow (Medium/Low)
        headerText = "🔸 Incident Report";
    }
}

// ==========================================
// ส่วนที่ 5: สร้าง Flex Message
// ==========================================
const flexContents = {
  type: "bubble",
  header: {
    type: "box", layout: "vertical", contents: [],
    backgroundColor: headerColor, paddingTop: "6px" 
  },
  body: {
    type: "box", layout: "vertical",
    contents: [
      { type: "text", text: headerText, weight: "bold", size: "xl", color: headerColor },
      {
        type: "box", layout: "vertical", margin: "lg", spacing: "sm",
        contents: [
          { type: "box", layout: "baseline", spacing: "sm", contents: [ { type: "text", text: "🎟️ Ticket:", color: "#aaaaaa", size: "sm", flex: 2, weight: "bold" }, { type: "text", text: ticketId, wrap: true, color: "#666666", size: "sm", flex: 5 } ] },
          { type: "box", layout: "baseline", spacing: "sm", contents: [ { type: "text", text: "👤 ผู้แจ้ง:", color: "#aaaaaa", size: "sm", flex: 2, weight: "bold" }, { type: "text", text: reporter, wrap: true, color: "#666666", size: "sm", flex: 5 } ] },
          { type: "box", layout: "baseline", spacing: "sm", contents: [ { type: "text", text: "🏢 ลูกค้า:", color: "#aaaaaa", size: "sm", flex: 2, weight: "bold" }, { type: "text", text: customerName, wrap: true, color: "#666666", size: "sm", flex: 5 } ] },
          { type: "box", layout: "baseline", spacing: "sm", contents: [ { type: "text", text: "☁️ บริการ:", color: "#aaaaaa", size: "sm", flex: 2, weight: "bold" }, { type: "text", text: serviceName, wrap: true, color: "#666666", size: "sm", flex: 5 } ] },
          { type: "separator", margin: "md" },
          { type: "box", layout: "baseline", spacing: "sm", margin: "md", contents: [ { type: "text", text: "📊 สถานะ:", color: "#aaaaaa", size: "sm", flex: 2, weight: "bold" }, { type: "text", text: status, wrap: true, color: "#1DB446", size: "sm", flex: 5, weight: "bold" } ] },
          { type: "box", layout: "baseline", spacing: "sm", contents: [ { type: "text", text: "📌 ประเภท:", color: "#aaaaaa", size: "sm", flex: 2, weight: "bold" }, { type: "text", text: `${issueType} (${priority})`, wrap: true, color: "#666666", size: "sm", flex: 5 } ] },
          { type: "box", layout: "baseline", spacing: "sm", contents: [ { type: "text", text: "📝 อาการ:", color: "#aaaaaa", size: "sm", flex: 2, weight: "bold" }, { type: "text", text: subject, wrap: true, color: "#666666", size: "sm", flex: 5 } ] },
          { type: "separator", margin: "md" },
          { type: "box", layout: "baseline", spacing: "sm", margin: "md", contents: [ { type: "text", text: "🕒 แจ้งเมื่อ:", color: "#aaaaaa", size: "sm", flex: 2, weight: "bold" }, { type: "text", text: createdTimeStr, wrap: true, color: "#666666", size: "sm", flex: 5 } ] },
          { type: "box", layout: "baseline", spacing: "sm", contents: [ { type: "text", text: "🏁 เสร็จใน:", color: "#aaaaaa", size: "sm", flex: 2, weight: "bold" }, { type: "text", text: dueTimeStr, wrap: true, color: "#FF6B6B", size: "sm", flex: 5, weight: "bold" } ] },
          { type: "separator", margin: "md" },
          { type: "text", text: "💡 ต้องการติดตามงาน แจ้ง Ticket ID กับ Admin ได้เลยครับ", size: "xs", color: "#aaaaaa", wrap: true, margin: "md", align: "center" }
        ]
      }
    ]
  }
};

if (imageUrl) {
  flexContents.hero = { type: "image", url: imageUrl, size: "full", aspectRatio: "20:13", aspectMode: "cover", action: { type: "uri", uri: imageUrl } };
  flexContents.footer = { type: "box", layout: "vertical", spacing: "sm", contents: [ { type: "button", style: "primary", height: "sm", action: { type: "uri", label: "🖼️ ดูรูปภาพเต็ม", uri: imageUrl }, color: headerColor } ], flex: 0 };
}

return {
  ticket_id: ticketId,
  Reporter_Name: reporter,
  Customer_Name: customerName,
  Service_Name: serviceName,
  type: issueType,
  priority: priority,
  Subject: subject,
  status: status,      
  assignee: assignee,  
  sla_minutes: sla_minutes,
  sla_display: slaText,
  created_at: createdTimeStr,
  due_date: due_at.toISOString(),
  due_date_display: dueTimeStr,
  Image_Evidence: imageUrl || '',
  line_payload: {
    to: "U39ad8f7118178f72fa5a8dde0b1c598a", 
    messages: [ { type: "flex", altText: `⚡ ${headerText}`, contents: flexContents } ]
  }
};

// 1. ดึงข้อมูล Pivot (ปัจจุบัน)
const pivotItems = $('Get row(s) in sheet5').all();

// 2. ดึงข้อมูล Log (อดีต)
const logItems = $('Get row(s) in sheet6').all();
const lastWeek = logItems.length > 0 ? logItems[0].json : {};

// ฟังก์ชันค้นหา
function getCurVal(keyword) {
  const row = pivotItems.find(i => {
    const stage = (i.json['Stage'] || '').toString();
    return stage.includes(keyword);
  });
  return row ? parseInt(row.json['COUNTA ของ บริษัท'] || 0) : 0;
}

// 3. Mapping ข้อมูล
const stats = {
  PO:       { cur: getCurVal('4. PO'),              last: parseInt(lastWeek.PO || 0) },
  Present:  { cur: getCurVal('2.1 Present แล้วสนใจ'), last: parseInt(lastWeek.Present || 0) },
  Brochure: { cur: getCurVal('1.1 สนใจรอ Slot') + getCurVal('1.2 ได้ Slot'), last: parseInt(lastWeek.Brochure || 0) },
  POC:      { cur: getCurVal('3.1 POC'),            last: parseInt(lastWeek.POC || 0) },

  // [แก้ไขจุดที่สั่ง]: เปลี่ยน Keyword จาก '3.2 QT' เป็น '3.3 POC และ QT'
  QT:       { cur: getCurVal('3.3 POC และ QT'),     last: parseInt(lastWeek.QT || 0) },

  Cancel:   { cur: getCurVal('6.2 Cancel Present'), last: parseInt(lastWeek.Cancel || 0) },
  Lost:     { cur: getCurVal('8. Lost'),            last: parseInt(lastWeek.Lost || 0) }
};

// 4. คำนวณ Trend
function calcTrend(curr, last, isGoodMetric) {
  const diff = curr - last;
  let percent = 0;
  if (last > 0) percent = Math.round((diff / last) * 100);

  let color = "#9CA3AF"; 
  let icon = ""; 
  let text = ""; 
  let hasChange = false; 

  if (diff > 0) {
    icon = "▲ " + diff;
    text = `▲ ${diff} (+${percent}%)`;
    color = isGoodMetric ? "#065F46" : "#991B1B";
    hasChange = true;
  } else if (diff < 0) {
    icon = "▼ " + Math.abs(diff);
    text = `▼ ${Math.abs(diff)} (${percent}%)`;
    color = isGoodMetric ? "#991B1B" : "#065F46";
    hasChange = true;
  }

  return { value: curr, icon: icon, text: text, color: color, hasChange: hasChange };
}

// 5. ประมวลผล
const po = calcTrend(stats.PO.cur, stats.PO.last, true);
const present = calcTrend(stats.Present.cur, stats.Present.last, true);
const brochure = calcTrend(stats.Brochure.cur, stats.Brochure.last, true);
const poc = calcTrend(stats.POC.cur, stats.POC.last, true);
const qt = calcTrend(stats.QT.cur, stats.QT.last, true);
const cancel = calcTrend(stats.Cancel.cur, stats.Cancel.last, false);
const lost = calcTrend(stats.Lost.cur, stats.Lost.last, false);

const today = new Date().toLocaleDateString('th-TH', { day: 'numeric', month: 'short', year: 'numeric' });

// ==========================================
// Helper Function: สร้างกล่องข้อมูลย่อย
// ==========================================
function createStatItem(label, dataObj, valueColor) {
    const contents = [
        { "type": "text", "text": `${dataObj.value}`, "size": "xl", "weight": "bold", "color": valueColor }
    ];

    if (dataObj.hasChange) {
        contents.push({ 
            "type": "text", 
            "text": dataObj.icon, 
            "size": "xs", 
            "color": dataObj.color, 
            "weight": "bold", 
            "margin": "sm" 
        });
    }

    return {
        "type": "box", "layout": "vertical", "flex": 1,
        "contents": [
            { "type": "text", "text": label, "size": "xxs", "color": "#6B7280", "align": "start", "wrap": true },
            {
                "type": "box", "layout": "baseline", "justifyContent": "flex-start",
                "contents": contents 
            }
        ]
    };
}

// ==========================================
// 6. เตรียมเนื้อหา PO CARD (Dynamic)
// ==========================================
const poContents = [];
poContents.push({ "type": "text", "text": "PURCHASE ORDER (PO)", "weight": "bold", "size": "xs", "color": "#FFFFFF", "align": "center", "wrap": true });
poContents.push({ "type": "text", "text": `${po.value}`, "weight": "bold", "size": "5xl", "color": "#FFFFFF", "align": "center", "margin": "sm" });

if (po.hasChange) {
    poContents.push({
       "type": "box", "layout": "horizontal",
       "contents": [ { "type": "text", "text": po.text, "size": "xs", "color": po.color, "weight": "bold", "align": "center" } ],
       "backgroundColor": "#D1FAE5", 
       "cornerRadius": "xxl",
       "paddingStart": "md", "paddingEnd": "md", "paddingTop": "xs", "paddingBottom": "xs",
       "margin": "sm", "justifyContent": "center"    
    });
}

// ==========================================
// 7. FLEX MESSAGE FINAL
// ==========================================
const flexMessage = {
  "type": "flex",
  "altText": `Weekly Update: PO ${po.value}`,
  "contents": {
    "type": "bubble",
    "size": "mega",
    "header": {
      "type": "box", "layout": "vertical",
      "contents": [
        {
          "type": "box", "layout": "horizontal",
          "contents": [
            { "type": "text", "text": "WEEKLY PERFORMANCE", "weight": "bold", "color": "#1E3A8A", "size": "xs", "flex": 1 },
            { "type": "text", "text": today, "size": "xxs", "color": "#6B7280", "align": "end" }
          ]
        },
        { "type": "text", "text": "Business Development Insight", "size": "lg", "weight": "bold", "color": "#111827", "margin": "xs", "wrap": true }
      ],
      "paddingAll": "lg",
      "backgroundColor": "#F3F4F6"
    },
    "body": {
      "type": "box", "layout": "vertical",
      "backgroundColor": "#F3F4F6", 
      "contents": [

        // --- 1. PO CARD (Green) ---
        {
          "type": "box", "layout": "vertical",
          "contents": poContents,    
          "alignItems": "center",    
          "paddingAll": "xxl",       
          "backgroundColor": "#047857", 
          "cornerRadius": "lg",
          "margin": "md"
        },

        // --- 2. PIPELINE CARD (White) ---
        {
           "type": "box", "layout": "vertical", "margin": "lg",
           "backgroundColor": "#FFFFFF", "cornerRadius": "lg", "paddingAll": "xl",           
           "contents": [
             { "type": "text", "text": "ACTIVE PIPELINE", "size": "xs", "weight": "bold", "color": "#4B5563", "margin": "sm", "align": "center" },
             { "type": "separator", "margin": "md", "color": "#F3F4F6" },
             // Row 1
             {
               "type": "box", "layout": "horizontal", "margin": "lg",
               "contents": [
                 createStatItem("Present แล้วสนใจ", present, "#1F2937"),
                 createStatItem("รอคิว/นัดนำเสนอ", brochure, "#1F2937")
               ]
             },
             // Row 2
             {
               "type": "box", "layout": "horizontal", "margin": "lg",
               "contents": [
                 createStatItem("POC (ทดสอบ)", poc, "#1F2937"),
                 createStatItem("POC และ QT", qt, "#1F2937")
               ]
             }
           ]
        },

        // --- 3. RISK CARD (White) ---
        {
           "type": "box", "layout": "vertical", "margin": "lg",
           "backgroundColor": "#FFFFFF", "cornerRadius": "lg", "paddingAll": "xl",
           "contents": [
             { "type": "text", "text": "RISK & LOSS", "size": "xs", "weight": "bold", "color": "#991B1B", "margin": "sm", "align": "center" },
             { "type": "separator", "margin": "md", "color": "#F3F4F6" },
             {
               "type": "box", "layout": "horizontal", "margin": "lg",
               "contents": [
