const text = subject.toLowerCase();
const failureKeywords = ['ไม่ได้', 'not', 'error', 'fail', 'พัง', 'เสีย', 'ล่ม', 'เข้าไม่', 'bug', 'ผิดพลาด', 'ไม่ขึ้น', 'ไม่แสดง', 'cannot', 'รายงานผิด'];
const requestKeywords = ['ขอ', 'request', 'เพิ่ม', 'ปรับ', 'แก้ไข', 'install', 'ติดตั้ง', 'สร้าง', 'create', 'new user', 'access'];

if (failureKeywords.some(k => text.includes(k))) { issueType = 'Incident'; }
else if (requestKeywords.some(k => text.includes(k))) { issueType = 'Request'; }

let priority = 'P3';
let sla_minutes = 480; 

if (issueType === 'Request') {
    priority = 'P4';
    sla_minutes = 1440; 
} else {
    if (text.includes('ล่ม') || text.includes('ใช้งานไม่ได้ทั้งหมด') || text.includes('เข้าไม่ได้') || text.includes('down') || text.includes('critical') || text.includes('ออกรายงานไม่ได้') || text.includes('รายงานผิด')) {
        priority = 'P1'; sla_minutes = 43; 
    } else if (text.includes('ไม่ได้') || text.includes('error') || text.includes('fail') || text.includes('ไม่ขึ้น')) {
        priority = 'P2'; sla_minutes = 120; 
    } else if (text.includes('บางส่วน') || text.includes('ช้า')) {
        priority = 'P3'; sla_minutes = 240; 
    } else {
        priority = 'P4'; sla_minutes = 1440; 
    }
}

let slaText = "";
if (sla_minutes >= 60) {
    const hrs = Math.floor(sla_minutes / 60);
    const mins = sla_minutes % 60;
    slaText = mins === 0 ? `${hrs} ชั่วโมง` : `${hrs} ชม. ${mins} นาที`;
} else {
    slaText = `${sla_minutes} นาที`;
}

// ==========================================
// ส่วนที่ 3: จัดการเวลา
// ==========================================
const now = new Date();
function formatDateTime(dateObj) {
    const d = String(dateObj.getDate()).padStart(2, '0');
    const m = String(dateObj.getMonth() + 1).padStart(2, '0');
    const y = dateObj.getFullYear();
    const hr = String(dateObj.getHours()).padStart(2, '0');
    const min = String(dateObj.getMinutes()).padStart(2, '0');
    return `${d}/${m}/${y} ${hr}:${min}`;
}
const createdTimeStr = formatDateTime(now);
const due_at = new Date(now.getTime() + sla_minutes * 60 * 1000);
const dueTimeStr = formatDateTime(due_at);

const y_id = now.getFullYear().toString().slice(2);
const m_id = String(now.getMonth() + 1).padStart(2, '0');
const d_id = String(now.getDate()).padStart(2, '0');
const randomNum = Math.floor(Math.random() * 900 + 100); 
const ticketId = `OCM-${y_id}${m_id}${d_id}-${randomNum}`;
const status = "🆕 รับเรื่องแล้ว";
const assignee = issueType === 'Incident' ? 'Team Infra' : 'Service Desk';

