    } else if (priority === 'P2') {
        headerColor = "#F57C00"; // Orange (High)
        headerText = "⚠️ High Priority Incident";
    } else {
        headerColor = "#FBC02D"; // Yellow (Medium/Low)
        headerText = "🔸 Incident Report";
    }
}

// ==========================================
// ส่วนที่ 5: สร้าง Flex Message
// ==========================================
const flexContents = {
