// รับข้อมูล Event จาก Node เริ่มต้น (แก้ชื่อ 'Master Router' ถ้าท่านใช้ชื่ออื่น)
const event = $('Master Router').first().json.body.events[0];
const message = event.message;
const messageId = message.id;

// 1. สร้างชื่อจากวันและเวลา (เช่น 2026-01-29_15-30)
const msgDate = new Date(event.timestamp);
// ตั้งค่าเวลาเป็นไทย
const dateStr = msgDate.toLocaleString("en-GB", { timeZone: "Asia/Bangkok", hour12: false })
                  .replace(/\//g, '-')   // เปลี่ยน / เป็น -
                  .replace(/:/g, '-')    // เปลี่ยน : เป็น -
                  .replace(', ', '_');   // เปลี่ยนช่องว่าง เป็น _

// 2. ตรวจสอบประเภทไฟล์
let filename = `unknown_${messageId}`;

if (message.type === 'image') {
  // ตั้งชื่อรูปเป็น: วันเวลา_IMAGE.jpg
  filename = `${dateStr}_IMAGE.jpg`; 
} 
else if (message.type === 'file') {
  // ถ้าเป็นไฟล์ ให้ใช้ชื่อเดิมที่คนส่งตั้งมา แต่เติมวันที่ข้างหน้า
  const originalName = message.fileName || `file_${messageId}`;
  filename = `${dateStr}_${originalName}`;
}

// 3. ยัดชื่อใหม่ใส่เข้าไปในไฟล์
const item = $input.item;
const binaryData = item.binary.data;
binaryData.fileName = filename;

return {
  json: {
    original_filename: filename // ส่งชื่อไปให้ Google Drive ใช้
  },
  binary: {
    data: binaryData
  }
};

